  p { color: #a6aeba; font-size: 12px; margin: 0 0 15px }
</style>
<main>
  <canvas id="film" width="960" height="540"
          aria-label="Walk Anyway, a thirty-second animated short film"></canvas>
  <button id="play">Play film</button>
  <p>30 seconds · 16:9 · rain and one spoken line · plays once</p>
</main>
<script>
"use strict";
const canvas = document.getElementById("film");
const c = canvas.getContext("2d");
const button = document.getElementById("play");
let running = false, started = 0, spoken = false;
let sound, rainGain, rainSource;
const W = 960, H = 540;
const drops = Array.from({length: 390}, (_, i) => ({
  x: ((i * 719 + 31) % 1200),
  y: ((i * 137 + 17) % 600),
  speed: 230 + (i % 9) * 27,
  length: 9 + (i % 5) * 4
}));

function rect(x,y,w,h,color) {
  c.fillStyle=color; c.fillRect(x,y,w,h);
}
function ellipse(x,y,rx,ry,color) {
  c.fillStyle=color; c.beginPath();
  c.ellipse(x,y,rx,ry,0,0,Math.PI*2); c.fill();
}
function path(points,color) {
  c.fillStyle=color; c.beginPath();
  points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));
  c.closePath(); c.fill();
}
function line(x,y,X,Y,color,width=2) {
  c.strokeStyle=color; c.lineWidth=width; c.lineCap="round";
  c.beginPath(); c.moveTo(x,y); c.lineTo(X,Y); c.stroke();
}
function title() {
  rect(0,0,W,H,"#000");
  c.fillStyle="#fff"; c.textAlign="center"; c.textBaseline="middle";
  c.font="500 48px Arial, sans-serif";
  c.fillText("WALK ANYWAY",480,270);
}
function background(t) {
  let sky=c.createLinearGradient(0,0,0,540);
  sky.addColorStop(0,"#080f1d");
  sky.addColorStop(.68,"#1c2b38");
  sky.addColorStop(1,"#09121b");
  c.fillStyle=sky; c.fillRect(0,0,960,540);

