  for(let i=0;i<65;i++){
    const x=(i*83)%960, y=367+(i*29)%169;
    rect(x,y,15+(i%5)*14,1,
      i%3===0?"#394a52":"#263c49");
  }
  let glow=c.createRadialGradient(360,250,10,360,250,260);
  glow.addColorStop(0,"rgba(207,200,156,.12)");
  glow.addColorStop(1,"rgba(207,200,156,0)");
  c.fillStyle=glow; c.fillRect(0,0,700,540);

  // Bus shelter.
  rect(180,204,344,14,"#46525a");
  rect(190,218,7,174,"#66717a");
  rect(510,218,7,174,"#66717a");
  rect(200,222,304,132,"rgba(156,182,188,.075)");
  line(350,221,350,352,"#46535d",3);
  rect(213,225,279,4,"#d4cfa7");
  rect(227,349,233,7,"#5a6569");
  rect(243,356,5,35,"#55616a");
  rect(443,356,5,35,"#55616a");
  line(566,174,566,393,"#596b7b",4);
  rect(550,160,32,28,"#344e66");
  // Bus symbol without lettering.
  rect(558,166,16,13,"#b0c1ca");
  rect(561,169,10,5,"#344e66");
  ellipse(561,181,2,2,"#b0c1ca");
  ellipse(571,181,2,2,"#b0c1ca");
}
function rain(t,close=false) {
  c.save();
  c.strokeStyle=close?"rgba(186,207,223,.31)":"rgba(176,200,220,.24)";
  c.lineWidth=close?1.5:1;
  c.beginPath();
  for(const d of drops){
    const x=(d.x-t*46+2400)%1200-120;
    const y=(d.y+t*d.speed)%600-35;
    c.moveTo(x,y); c.lineTo(x-4,y+d.length);
  }
  c.stroke(); c.restore();
}
function woman(x,y,s,t,back=false,smile=false,walking=false) {
  c.save(); c.translate(x,y); c.scale(s,s);
  const swing=walking?Math.sin(t*5)*7:0;
  ellipse(0,2,28,5,"rgba(0,0,0,.3)");
  // Yellow boots remain visible in the wide and rear shots.
  rect(-16+swing,-38,12,36,"#d7ae36");
  rect(5-swing,-38,12,36,"#d7ae36");
  rect(-18+swing,-9,18,9,"#e2b83e");
  rect(5-swing,-9,18,9,"#e2b83e");
  path([[-18,-143],[18,-143],[30,-38],[-29,-38]],"#af3440");
  path([[-18,-141],[-29,-130],[-36,-77],[-25,-73],[-10,-121]],"#9b2937");
  path([[18,-141],[29,-130],[34,-76],[24,-73],[10,-121]],"#be3a46");
  line(0,-135,0,-43,"#dd6667",1.5);
  ellipse(0,-164,18,25,"#d6b4a0");
  // Distinctive straight silver bob.
  c.fillStyle="#c9cdd4"; c.beginPath();
  c.moveTo(-22,-153); c.lineTo(-22,-176);
  c.bezierCurveTo(-19,-203,20,-203,23,-176);
  c.lineTo(23,-151); c.lineTo(13,-151);
  c.lineTo(12,-179); c.lineTo(-11,-179);
  c.lineTo(-13,-151); c.closePath(); c.fill();
  if(back) {
    path([[-22,-180],[22,-180],[23,-150],[-22,-150]],"#bdc3cd");
    line(-11,-184,-12,-155,"#e0e3e8",2);
  } else {
    ellipse(-7,-166,1.5,1.5,"#353441");
    ellipse(7,-166,1.5,1.5,"#353441");
    c.strokeStyle="#85544f"; c.lineWidth=1.6; c.beginPath();
    c.moveTo(-5,-153);
    c.quadraticCurveTo(0,smile?-147:-152,6,-154);
    c.stroke();
  }
  c.restore();
}
function man(x,y,s,t,back=false,walking=false) {
  c.save(); c.translate(x,y); c.scale(s,s);
  const swing=walking?Math.sin(t*5+1.8)*6:0;
  ellipse(0,2,27,5,"rgba(0,0,0,.3)");
  rect(-16+swing,-49,12,47,"#252b31");
  rect(5-swing,-49,12,47,"#252b31");
  rect(-20+swing,-9,20,9,"#131a23");
  rect(5-swing,-9,21,9,"#131a23");
  path([[-21,-132],[20,-132],[29,-44],[-29,-44]],"#45594c");
  path([[-20,-131],[-31,-119],[-33,-75],[-22,-72],[-11,-118]],"#394e43");
  path([[20,-131],[30,-119],[29,-83],[18,-83],[11,-117]],"#506352");
  line(0,-125,0,-49,"#657769",1.5);
  ellipse(0,-153,20,26,"#c5a18b");
  // Grey hair and a full grey beard.
  c.fillStyle="#909699"; c.beginPath();
  c.arc(0,-161,21,Math.PI,Math.PI*2);
  c.lineTo(20,-151); c.lineTo(14,-167);
  c.lineTo(-13,-168); c.lineTo(-19,-149); c.fill();
  if(back) {
    ellipse(0,-155,19,25,"#92999c");
    ellipse(0,-157,13,17,"#a0a6a7");
  } else {
    path([[-19,-150],[-13,-133],[0,-124],[14,-134],[19,-151],
          [9,-145],[0,-141],[-9,-146]],"#b1b4b2");
    ellipse(-7,-155,1.5,1.5,"#34343a");
    ellipse(7,-155,1.5,1.5,"#34343a");
    line(-5,-139,6,-139,"#635958",1.5);
  }
  // Hand holding umbrella shaft.
  line(24,-91,41,-108,"#506352",10);
  ellipse(42,-109,5,5,"#c5a18b");
  c.restore();
}
function umbrella(x,y,s) {
  c.save(); c.translate(x,y); c.scale(s,s);
  line(0,0,0,111,"#8c969c",2.5);
  c.strokeStyle="#8c969c"; c.lineWidth=2.5;
  c.beginPath(); c.arc(-6,111,6,0,Math.PI); c.stroke();
  c.fillStyle="#0b111b"; c.beginPath();
  c.moveTo(-91,0);
  c.bezierCurveTo(-70,-70,65,-75,94,0);
  c.quadraticCurveTo(70,-10,47,0);
  c.quadraticCurveTo(22,-10,0,0);
  c.quadraticCurveTo(-23,-10,-46,0);
  c.quadraticCurveTo(-68,-11,-91,0); c.fill();
  line(0,-51,0,-62,"#131b27",2);
  c.strokeStyle="#26303c"; c.lineWidth=1;
  for(const edge of [-91,-46,0,47,94]){
    c.beginPath(); c.moveTo(0,-52);
    c.quadraticCurveTo(edge*.6,-41,edge,0); c.stroke();
  }
  c.restore();
}
function wide(t,arrival) {
  background(t);
  woman(420,412,1,t);
  if(arrival) {
    const p=Math.min(1,Math.max(0,(t-9)/5.6));
    const x=765-275*p;
    man(x,414,1,t,false,p<1);
    umbrella(x+42,183,1);
  }
  rain(t);
}
function close(t) {
  background(t);
  // A closer camera view keeps the same character drawings and wardrobe.
  c.save();
  c.translate(-810,-276); c.scale(2.75,2.75);
  woman(420,412,1,t,false,t>=18.1);
  man(479,414,1,t);
  umbrella(521,183,1);
  c.restore();
  rain(t,true);
  // Subtle vignette.
  const v=c.createRadialGradient(480,255,150,480,255,590);
  v.addColorStop(0,"rgba(0,0,0,0)");
  v.addColorStop(1,"rgba(0,0,0,.48)");
  c.fillStyle=v; c.fillRect(0,0,960,540);
}
function departure(t) {
  background(t);
  const p=Math.min(1,(t-22)/6);
  const scale=1-p*.34;
  const x=471+p*94, y=427-p*67;
  c.save(); c.translate(x,y); c.scale(scale,scale);
  woman(-34,0,1,t,true,false,true);
  man(34,0,1,t,true,true);
  umbrella(32,-233,1.08);
  c.restore();
  rain(t);
