function frame(t) {
  if(t<2 || t>=28) title();
  else if(t<9) wide(t,false);
  else if(t<16) wide(t,true);
  else if(t<22) close(t);
  else departure(t);
}
function prepareRain() {
  const AudioContext=window.AudioContext||window.webkitAudioContext;
  if(!AudioContext) return;
  sound=new AudioContext();
  const buffer=sound.createBuffer(1,sound.sampleRate*3,sound.sampleRate);
  const data=buffer.getChannelData(0);
  for(let i=0;i<data.length;i++) data[i]=(Math.random()*2-1)*.55;
  rainSource=sound.createBufferSource();
  rainSource.buffer=buffer; rainSource.loop=true;
  const high=sound.createBiquadFilter();
  high.type="highpass"; high.frequency.value=650;
  const low=sound.createBiquadFilter();
  low.type="lowpass"; low.frequency.value=6800;
  rainGain=sound.createGain(); rainGain.gain.value=0;
  rainSource.connect(high); high.connect(low);
  low.connect(rainGain); rainGain.connect(sound.destination);
  rainSource.start(); sound.resume();
}
function sayLine() {
  if(!("speechSynthesis" in window)) return;
  const u=new SpeechSynthesisUtterance("You came back.");
  const voices=speechSynthesis.getVoices();
  const english=voices.filter(v=>/^en/i.test(v.lang));
  const male=english.find(v=>/david|daniel|george|james|mark|guy/i.test(v.name));
  if(male||english[0]) u.voice=male||english[0];
  u.lang="en-US"; u.rate=.78; u.pitch=.74; u.volume=.9;
  speechSynthesis.speak(u);
}
function tick(now) {
  if(!running) return;
  const t=Math.min(30,(now-started)/1000);
  frame(t);
  if(rainGain) {
    let level=t<2||t>=28?0:.18;
    if(t>=16.65&&t<19.4) level=.105;
    rainGain.gain.setTargetAtTime(level,sound.currentTime,.12);
  }
  if(t>=16.8&&!spoken) { spoken=true; sayLine(); }
  if(t<30) requestAnimationFrame(tick);
  else stop();
}
function stop() {
  running=false; title(); button.textContent="Replay film";
  if("speechSynthesis" in window) speechSynthesis.cancel();
  if(sound) {
    const old=sound; sound=null; rainGain=null;
    old.close().catch(()=>{});
  }
}
button.onclick=()=>{
  if(running) { stop(); return; }
  if("speechSynthesis" in window) speechSynthesis.cancel();
  spoken=false; running=true;
  prepareRain(); started=performance.now();
  button.textContent="Stop";
  requestAnimationFrame(tick);
};
if("speechSynthesis" in window) speechSynthesis.getVoices();
title();
</script>
</html>
